-- admbank_prosp_b_build | disc_model_owner.admbank_prosp_202608: BASE ADMBANKBPE del ultimo mes (p_codmes=202608) con TODAS las filas scoreadas + flags y PDs.
--   flg_camp: 1 = entra a campana | 0 = cae (esta en disc_model_owner.caidas_202608_admbank por key_value, anti-marca)
--   prob_modelo_cal = PD DSM (=pd_pit_final: 4seg isotonica + PBI AnclaB + overlay PJ x0.85). grupos_cal = G1-G6 cortes [971, 945, 921, 908, 893].
--   pd_v2_esc_opt = PD V2 lineage-A (nivel personeria + rho Basel + Vasicek fhat + re-ancla + factor esc_opt). puntuacion_v2 = round((1-pd_v2)*1000).
--   grupos_ant = nivel_riesgo del banco (Bajo/Medio Bajo/Medio/Medio Alto/Alto) sobre 1-puntaje_v2/1000, adaptado al puntaje V2. desc_cliente_cal derivado del stock (M-1).
--   Un solo mes -> ft PBI y fhat V2 son constantes (0.0790 / -0.0214). Calibracion validada 1e-11.
CREATE TABLE disc_model_owner.admbank_prosp_202608
WITH (format='PARQUET', parquet_compression='SNAPPY') AS
WITH stk AS (
  SELECT DISTINCT CAST(tip_doc AS VARCHAR) AS tip_doc, key_value, CAST(codmes AS INT) AS codmes
  FROM e_perm_aws.scr_cmpbpeibk2_rsk WHERE CAST(codmes AS INT)=202607
),
b AS (
  SELECT s.*,
    CAST(s.p_codmes AS INT) AS _pcm,
    (CASE WHEN s.tip_doc='1' THEN 'PN' ELSE 'PJ' END || '_' || CASE WHEN st.key_value IS NOT NULL THEN 'RECURRENTE' ELSE 'NUEVO' END) AS _seg,
    CASE WHEN st.key_value IS NOT NULL THEN 'RECURRENTE' ELSE 'NUEVO' END AS desc_cliente_cal,
    CASE WHEN cd.key_value IS NOT NULL THEN 0 ELSE 1 END AS flg_camp,
    greatest(1e-4, least(1-1e-4, CAST(s.probabilidad AS DOUBLE))) AS _pdraw,
    greatest(1e-6, least(1-1e-6, CAST(s.probabilidad AS DOUBLE))) AS _pc
  FROM e_perm_aws.scr_admbankbpe_rsk s
  LEFT JOIN stk st ON st.tip_doc=s.tip_doc AND st.key_value=s.key_value AND st.codmes=CAST(s.codmes AS INT)
  LEFT JOIN disc_model_owner.caidas_202608_admbank cd ON cd.key_value=s.key_value
  WHERE s.p_codmes='202608' AND s.probabilidad IS NOT NULL AND s.modelo='ADMBANKBPE'
),
