  f.prob_modelo_cal,
  CAST(round((1.0-f.prob_modelo_cal)*1000) AS INTEGER) AS puntuacion_cal,
  CASE WHEN round((1.0-f.prob_modelo_cal)*1000) >= 971 THEN 'G1' WHEN round((1.0-f.prob_modelo_cal)*1000) >= 945 THEN 'G2' WHEN round((1.0-f.prob_modelo_cal)*1000) >= 921 THEN 'G3' WHEN round((1.0-f.prob_modelo_cal)*1000) >= 908 THEN 'G4' WHEN round((1.0-f.prob_modelo_cal)*1000) >= 893 THEN 'G5' ELSE 'G6' END AS grupos_cal,
  f.pd_v2_esc_opt,
  CAST(round((1.0-f.pd_v2_esc_opt)*1000) AS INTEGER) AS puntuacion_v2,
  CASE WHEN 1.0-round((1.0-f.pd_v2_esc_opt)*1000)/1000.0 <= 0.0345 THEN 'Bajo' WHEN 1.0-round((1.0-f.pd_v2_esc_opt)*1000)/1000.0 <= 0.0575 THEN 'Medio Bajo' WHEN 1.0-round((1.0-f.pd_v2_esc_opt)*1000)/1000.0 <= 0.0785 THEN 'Medio' WHEN 1.0-round((1.0-f.pd_v2_esc_opt)*1000)/1000.0 <= 0.1295 THEN 'Medio Alto' ELSE 'Alto' END AS grupos_ant
FROM fin f
